    // names has both; sub-components attached to each other in a cycle end at the first path that reaches them.
    let source = r#"
        interface P { label: string }
        function Item(props: P) { return <li />; }
        function Menu(props: P) { return <ul />; }
        Menu.Item = Item;
        export default Menu;
        function Ping(props: P) { return <i />; }
        function Pong(props: P) { return <u />; }
        Ping.Pong = Pong;
        Pong.Ping = Ping;
        export { Ping as Game };
    "#;
    assert_eq!(
        exports("/test/menu.tsx", source),
        named(&[("Item", &["default.Item"]), ("Menu", &["default"]), ("Ping", &["Game"]), ("Pong", &["Game.Pong"]),])
    );
    assert_eq!(
        exports(
            "/test/twice.tsx",
            "export function Twice(props: { a: string }) { return <b />; } export default Twice;"
        ),
        named(&[("Twice", &["Twice", "default"])])
    );
}

#[test]
fn an_inline_sub_component_has_only_the_exports_of_the_parent_it_is_attached_to() {
    // Each mapping is told apart by its props type, as its name `Item` is shared.
    let exports = |source: &str| -> Vec<(String, String, Vec<String>)> {
        let data = parse_file(Utf8Path::new("/test/items.tsx"), source);
        let mut found: Vec<(String, String, Vec<String>)> = data
            .component_mappings
            .iter()
            .map(|m| {
                (
                    m.component_name.to_string(),
                    m.props_type_name.to_string(),
                    m.exports.iter().map(ToString::to_string).collect(),
                )
            })
            .collect();
        found.sort_unstable();
        found
    };
    let row = |name: &str, props: &str, exports: &[&str]| {
        (name.to_string(), props.to_string(), exports.iter().map(ToString::to_string).collect::<Vec<_>>())
    };
    let source = r#"
        interface AProps { a: string }
        interface BProps { b: string }
        export function A(props: AProps) { return <ul />; }
        export function B(props: BProps) { return <ol />; }
        A.Item = (props: AProps) => <li />;
        B.Item = (props: BProps) => <li />;
    "#;
    assert_eq!(
        exports(source),
        [
            row("A", "AProps", &["A"]),
            row("B", "BProps", &["B"]),
            row("Item", "AProps", &["A.Item"]),
            row("Item", "BProps", &["B.Item"])
        ]
    );
    let source = r#"
        interface AProps { a: string }
        interface BProps { b: string }
        interface CProps { c: string }
        function ARoot(props: AProps) { return <ul />; }
        vec![
            ("Memoized", "BaseProps", ForwardRef),
            ("Overlay", "OverlayProps", WrapperTypeArgument),
            ("Themed", "BaseProps", ForwardRef),
        ]
    );
}

#[test]
fn anonymous_default_exports_are_named_after_their_file() {
    let cases = [
        ("/test/chip.tsx", "interface ChipProps { a?: string }\nexport default (props: ChipProps) => <span />;\n"),
        (
            "/test/badge.tsx",
            "import { memo } from 'react';\ninterface BadgeProps { a?: string }\nexport default memo(function Badge(props: BadgeProps) { return <b />; });\n",
        ),
        (
            "/test/field.tsx",
            "import { forwardRef } from 'react';\ninterface FieldProps { a?: string }\nexport default forwardRef<HTMLInputElement, FieldProps>((props, ref) => <input ref={ref} />);\n",
        ),
        (
            "/test/panel.tsx",
            "import { Component } from 'react';\ninterface PanelProps { a?: string }\nexport default class extends Component<PanelProps> { render() { return <div />; } }\n",
        ),
    ];
    let found: Vec<(String, String)> = cases
        .iter()
        .flat_map(|(path, source)| {
            parse_file(Utf8Path::new(path), source)
                .component_mappings
                .into_iter()
                .map(|m| (m.component_name, m.props_type_name.to_string()))
        })
        .collect();
    let pair = |n: &str, p: &str| (n.to_owned(), p.to_owned());
    assert_eq!(
        found,
        vec![
            pair("Chip", "ChipProps"),
            pair("Badge", "BadgeProps"),
            pair("Field", "FieldProps"),
            pair("Panel", "PanelProps")
        ]
    );
}

